use std::fmt::Write;

const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];

fn csv_field(value: &str) -> String {
    if value.contains([',', '"', '\r', '\n']) {
        format!("\"{}\"", value.replace('"', "\"\""))
    } else {
        value.to_owned()
    }
}

fn csv(rows: &[(&str, u32)]) -> String {
    let mut output = String::from("name,count\n");
    for (name, count) in rows {
        writeln!(output, "{},{count}", csv_field(name)).unwrap();
    }
    output
}

fn main() {
    if std::env::args().skip(1).any(|arg| arg == "--csv") {
        print!("{}", csv(&TABLE));
    } else {
        for (name, count) in TABLE {
            println!("{name:<8}{count}");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exports_header_and_table_rows() {
        assert_eq!(csv(&TABLE), "name,count\napples,3\npears,5\nplums,2\n");
    }

    #[test]
    fn escapes_special_fields() {
        for (input, expected) in [
            ("plain", "plain"),
            ("", ""),
            ("a,b", "\"a,b\""),
            ("a\"b", "\"a\"\"b\""),
            ("a\nb", "\"a\nb\""),
            ("a\rb", "\"a\rb\""),
            ("a\r\nb", "\"a\r\nb\""),
        ] {
            assert_eq!(csv_field(input), expected);
        }
    }

    #[test]
    fn escapes_fields_in_rows() {
        assert_eq!(csv(&[("a,\"b\"\nc", 7)]), "name,count\n\"a,\"\"b\"\"\nc\",7\n");
    }

    #[test]
    fn empty_table_still_has_header() {
        assert_eq!(csv(&[]), "name,count\n");
    }
}

use std::fmt::Write;

const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];
const USAGE: &str = "usage: widget [--theme dark]";

#[derive(Clone, Copy, Debug, PartialEq)]
enum Theme {
    Plain,
    Dark,
}

fn parse_args<'a>(mut args: impl Iterator<Item = &'a str>) -> Result<Theme, &'static str> {
    match (args.next(), args.next(), args.next()) {
        (None, None, None) => Ok(Theme::Plain),
        (Some("--theme"), Some("dark"), None) => Ok(Theme::Dark),
        _ => Err(USAGE),
    }
}

fn render_table(theme: Theme) -> String {
    let mut output = String::new();
    if theme == Theme::Dark {
        // Bright white on black, independent of the terminal's default colors.
        output.push_str("\x1b[97;40m");
    }
    for (name, count) in TABLE {
        writeln!(output, "{name:<8}{count}").expect("writing to a String cannot fail");
    }
    if theme == Theme::Dark {
        output.push_str("\x1b[0m");
    }
    output
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match parse_args(args.iter().map(String::as_str)) {
        Ok(theme) => print!("{}", render_table(theme)),
        Err(message) => {
            eprintln!("{message}");
            std::process::exit(2);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const PLAIN: &str = "apples  3\npears   5\nplums   2\n";

    #[test]
    fn default_output_is_unchanged() {
        assert_eq!(parse_args(std::iter::empty()), Ok(Theme::Plain));
        assert_eq!(render_table(Theme::Plain), PLAIN);
    }

    #[test]
    fn dark_output_has_colors_and_final_reset() {
        assert_eq!(parse_args(["--theme", "dark"].iter().copied()), Ok(Theme::Dark));
        assert_eq!(render_table(Theme::Dark), format!("\x1b[97;40m{}\x1b[0m", PLAIN));
    }

    #[test]
    fn invalid_arguments_are_rejected() {
        for args in [
            vec!["--theme"],
            vec!["--theme", "light"],
            vec!["--theme", ""],
            vec!["--theme=dark"],
            vec!["dark"],
            vec!["--unknown"],
            vec!["--theme", "dark", "extra"],
            vec!["--theme", "dark", "--theme", "dark"],
        ] {
            assert_eq!(parse_args(args.iter().copied()), Err(USAGE), "{:?}", args);
        }
    }
}

const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];

fn render_table(query: Option<&str>) -> String {
    let query = query.unwrap_or_default().trim().to_lowercase();
    let mut output = String::new();
    for (name, count) in TABLE {
        if name.to_lowercase().contains(&query) {
            output.push_str(&format!("{name:<8}{count}\n"));
        }
    }
    if output.is_empty() {
        output.push_str("No results found.\n");
    }
    output
}

fn main() {
    let query = std::env::args().nth(1);
    print!("{}", render_table(query.as_deref()));
}

#[cfg(test)]
mod tests {
    use super::render_table;

    const UNFILTERED: &str = "apples  3\npears   5\nplums   2\n";

    #[test]
    fn no_query_preserves_output() {
        assert_eq!(render_table(None), UNFILTERED);
    }

    #[test]
    fn unmatched_query_shows_empty_state() {
        assert_eq!(render_table(Some("oranges")), "No results found.\n");
    }

    #[test]
    fn search_is_case_insensitive_and_trimmed() {
        assert_eq!(render_table(Some("  PeA  ")), "pears   5\n");
    }

    #[test]
    fn blank_queries_are_unfiltered() {
        for query in ["", " \t\n "] {
            assert_eq!(render_table(Some(query)), UNFILTERED);
        }
    }
}

use std::fmt::Write;

const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];
const USAGE: &str = "usage: widget [--theme dark] [--csv]";

#[derive(Clone, Copy, Debug, PartialEq)]
enum Theme {
    Plain,
    Dark,
}

fn parse_args<'a>(mut args: impl Iterator<Item = &'a str>) -> Result<(Theme, bool), &'static str> {
    let mut theme = Theme::Plain;
    let mut export_csv = false;
    while let Some(arg) = args.next() {
        match arg {
            "--theme" if theme == Theme::Plain => {
                if args.next() != Some("dark") {
                    return Err(USAGE);
                }
                theme = Theme::Dark;
            }
            "--csv" if !export_csv => export_csv = true,
            _ => return Err(USAGE),
        }
    }
    Ok((theme, export_csv))
}

fn render_table(theme: Theme) -> String {
    let mut output = String::new();
    if theme == Theme::Dark {
        // Bright white on black, independent of the terminal's default colors.
        output.push_str("\x1b[97;40m");
    }
    for (name, count) in TABLE {
        writeln!(output, "{name:<8}{count}").expect("writing to a String cannot fail");
    }
    if theme == Theme::Dark {
        output.push_str("\x1b[0m");
    }
    output
}

fn csv_field(value: &str) -> String {
    if value.contains([',', '"', '\r', '\n']) {
        format!("\"{}\"", value.replace('"', "\"\""))
    } else {
        value.to_owned()
    }
}

fn csv(rows: &[(&str, u32)]) -> String {
    let mut output = String::from("name,count\n");
    for (name, count) in rows {
        writeln!(output, "{},{count}", csv_field(name)).unwrap();
    }
    output
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match parse_args(args.iter().map(String::as_str)) {
        Ok((_, true)) => print!("{}", csv(&TABLE)),
        Ok((theme, false)) => print!("{}", render_table(theme)),
        Err(message) => {
            eprintln!("{message}");
            std::process::exit(2);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    const PLAIN: &str = "apples  3\npears   5\nplums   2\n";

    #[test]
    fn default_output_is_unchanged() {
        assert_eq!(parse_args(std::iter::empty()), Ok((Theme::Plain, false)));
        assert_eq!(render_table(Theme::Plain), PLAIN);
    }

    #[test]
    fn dark_output_has_colors_and_final_reset() {
        assert_eq!(parse_args(["--theme", "dark"].into_iter()), Ok((Theme::Dark, false)));
        assert_eq!(render_table(Theme::Dark), format!("\x1b[97;40m{}\x1b[0m", PLAIN));
    }

    #[test]
    fn csv_options() {
        assert_eq!(parse_args(["--csv"].into_iter()), Ok((Theme::Plain, true)));
        for args in [["--csv", "--theme", "dark"], ["--theme", "dark", "--csv"]] {
            assert_eq!(parse_args(args.into_iter()), Ok((Theme::Dark, true)));
        }
        assert_eq!(csv(&TABLE), "name,count\napples,3\npears,5\nplums,2\n");
        assert_eq!(csv(&[]), "name,count\n");
    }

    #[test]
    fn invalid_arguments_are_rejected() {
        for args in [
            vec!["--theme"], vec!["--theme", "light"], vec!["--theme", ""],
            vec!["--theme=dark"], vec!["dark"], vec!["--unknown"],
            vec!["--theme", "dark", "extra"],
            vec!["--theme", "dark", "--theme", "dark"], vec!["--csv", "--csv"],
        ] {
            assert_eq!(parse_args(args.into_iter()), Err(USAGE));
        }
    }

    #[test]
    fn escapes_special_fields() {
        for (input, expected) in [
            ("plain", "plain"), ("", ""), ("a,b", "\"a,b\""),
            ("a\"b", "\"a\"\"b\""), ("a\nb", "\"a\nb\""),
            ("a\rb", "\"a\rb\""), ("a\r\nb", "\"a\r\nb\""),
        ] {
            assert_eq!(csv_field(input), expected);
        }
        assert_eq!(csv(&[("a,\"b\"\nc", 7)]), "name,count\n\"a,\"\"b\"\"\nc\",7\n");
    }
}
